import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.*;
import javax.imageio.ImageIO;

/** Вбудовані іконки завантажувачів (NeoForge, Forge, Quilt, Fabric). Vanilla бере блок землі з BlockTex. */
final class LoaderIcons {
    private LoaderIcons() { }

    private static final Map<String, String> DATA = new HashMap<>();
    private static final Map<String, BufferedImage> CACHE = new HashMap<>();

    static {
        DATA.put("NeoForge", String.join("", "", ""));
        DATA.put("Forge", String.join("", "", ""));
        DATA.put("Quilt", String.join("", "", "", ""));
        DATA.put("Fabric", String.join("", "", ""));
        DATA.put("Modrinth", String.join("", "", "", "", "", ""));
        DATA.put("CurseForge", "");
    }

    static boolean has(String name) { return DATA.containsKey(name); }

    static synchronized BufferedImage get(String name) {
        BufferedImage im = CACHE.get(name);
        if (im != null) return im;
        try {
            im = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(DATA.get(name))));
        } catch (Exception e) {
            im = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        }
        CACHE.put(name, im);
        return im;
    }

    /** Визначає завантажувач за ідентифікатором/описом версії (fabric-loader-…, 1.20.1-forge-…, neoforge-… тощо). */
    static String loaderOf(String text) {
        String t = text == null ? "" : text.toLowerCase(Locale.ROOT);
        if (t.contains("neoforge")) return "NeoForge";
        if (t.contains("quilt")) return "Quilt";
        if (t.contains("fabric")) return "Fabric";
        if (t.contains("forge")) return "Forge";
        return "Vanilla";
    }

    private static final Map<String, BufferedImage> SCALED = new HashMap<>();

    /** Іконка, заздалегідь зменшена до px×px поступовими кроками (без розмиття й «зубців» від одноразового сильного зменшення). */
    static synchronized BufferedImage scaled(String name, int px) {
        String key = name + "@" + px;
        BufferedImage r = SCALED.get(key);
        if (r != null) return r;
        if (name.equals("Vanilla")) r = BuildIcons.render("grass_block_side", px);
        else if (has(name)) r = ImgIcon.smooth(get(name), px, px);
        else r = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        SCALED.put(key, r);
        return r;
    }

    /** Малює іконку в квадрат s×s (координати поточної системи); сама враховує масштаб графіки, щоб піксель лягав у піксель. */
    static void draw(java.awt.Graphics2D g0, String name, int x, int y, int s) {
        if (s <= 0) return;
        double k = Math.abs(g0.getTransform().getScaleX());
        if (k < 1e-3) k = 1;
        int px = Math.max(1, (int) Math.round(s * k));
        java.awt.Graphics2D g = (java.awt.Graphics2D) g0.create();
        g.scale(1 / k, 1 / k);
        g.drawImage(scaled(name, px), (int) Math.round(x * k), (int) Math.round(y * k), null);
        g.dispose();
    }
}
